package org.retrobridge.play2012;
import android.app.*;import android.content.*;import android.content.pm.*;import android.net.Uri;import android.os.*;import android.widget.Toast;import java.io.*;import java.util.concurrent.*;import org.json.*;

/** Uses the original Store's progress and completion views. */
public final class PixelInstallerService extends IntentService {
 static final ConcurrentHashMap<String,Job> jobs=new ConcurrentHashMap<String,Job>();
 static final class Job{volatile String state="DOWNLOAD_PENDING";volatile long bytes,total;volatile boolean cancelled;}
 public PixelInstallerService(){super("Store installer");}
 static Object value(String type,String name)throws Exception{return java.lang.Enum.valueOf((Class)Class.forName(type),name);}
 public static Object state(String pkg){try{Job j=jobs.get(pkg);return value("com.google.android.finsky.receivers.Installer$InstallerState",j==null?"NOT_TRACKED":j.state);}catch(Exception e){throw new IllegalStateException(e);}}
 public static Object progress(String pkg){try{Job j=jobs.get(pkg);Class<?> st=Class.forName("com.google.android.finsky.receivers.Installer$InstallerState");return Class.forName("com.google.android.finsky.receivers.Installer$InstallerProgressReport").getConstructor(st,long.class,long.class,int.class).newInstance(state(pkg),j==null?0L:j.bytes,j==null?0L:j.total,2);}catch(Exception e){throw new IllegalStateException(e);}}
 static void signal(final String pkg,final String event,final int code){new Handler(Looper.getMainLooper()).post(new Runnable(){public void run(){try{Object installer=PixelCatalog.invoke(PixelCatalog.app(),"getInstaller");PixelCatalog.invoke(installer,"notifyListeners",pkg,value("com.google.android.finsky.installer.InstallerListener$InstallerPackageEvent",event),code);}catch(Exception e){android.util.Log.e("PixelInstaller","Progress callback failed",e);}}});}
 public static void cancel(String pkg){Job j=jobs.get(pkg);if(j!=null&&!j.state.equals("INSTALLING"))j.cancelled=true;}
 public static void start(Context c,String pkg)throws Exception{if(jobs.putIfAbsent(pkg,new Job())!=null)return;try{c.startService(new Intent(c,PixelInstallerService.class).putExtra("package",pkg));signal(pkg,"DOWNLOAD_PENDING",0);}catch(Exception e){jobs.remove(pkg);throw e;}}
 protected void onHandleIntent(Intent request){if(request==null)return;final String pkg=request.getStringExtra("package");final Job job=jobs.get(pkg);if(job==null)return;File part=null;boolean success=false;String error=null;
  try{Bundle ready=getContentResolver().call(Uri.parse("content://org.retrobridge.storeinstaller"),"status",null,null);if(ready==null||!ready.getBoolean("ready"))throw new IOException("Store installer needs setup");final JSONObject item=PixelCatalog.find(pkg);job.total=item.getLong("size");job.state="DOWNLOADING";signal(pkg,"DOWNLOADING",0);
   File dir=new File(Environment.getExternalStoragePublicDirectory(Environment.DIRECTORY_DOWNLOADS),"Galaxy Store");dir.mkdirs();File target=new File(dir,pkg+"-"+item.getInt("versionCode")+".apk");part=new File(target.toString()+".part");
   PixelCatalog.download(pkg,part,job.total,new PixelCatalog.Progress(){int last=-1;public void update(int count)throws IOException{if(job.cancelled)throw new IOException("Download cancelled");job.bytes=count;int percent=(int)(100L*count/job.total);if(percent!=last){last=percent;signal(pkg,"DOWNLOADING",0);}}});
   if(job.cancelled)throw new IOException("Download cancelled");if(part.length()!=job.total||!PixelInstall.hash(part).equals(item.getString("sha256")))throw new IOException("Download checksum mismatch");PackageInfo pi=getPackageManager().getPackageArchiveInfo(part.toString(),PackageManager.GET_SIGNATURES);if(pi==null||!pkg.equals(pi.packageName)||pi.versionCode!=item.getInt("versionCode")||pi.signatures==null||pi.signatures.length!=1||!PixelInstall.hash(pi.signatures[0].toByteArray()).equals(item.getString("signerSha256")))throw new IOException("Download signature mismatch");if(target.exists()&&!target.delete())throw new IOException("Cannot replace installer");if(!part.renameTo(target))throw new IOException("Cannot save installer");
   job.state="INSTALLING";signal(pkg,"INSTALLING",0);Bundle args=new Bundle();args.putString("package",pkg);args.putString("sha256",item.getString("sha256"));args.putString("signerSha256",item.getString("signerSha256"));args.putInt("versionCode",item.getInt("versionCode"));args.putLong("size",job.total);
   Bundle result=getContentResolver().call(Uri.parse("content://org.retrobridge.storeinstaller"),"install",null,args);if(result==null||result.getInt("code")!=1)throw new IOException(result==null?"Installer unavailable":result.getString("error"));success=true;
  }catch(Exception e){error=e.getMessage();android.util.Log.w("PixelInstaller",e.getClass().getSimpleName()+": "+error);}
  finally{if(part!=null)part.delete();jobs.remove(pkg);signal(pkg,success?"INSTALLED":job.cancelled?"DOWNLOAD_CANCELLED":"INSTALL_ERROR",success?1:-1);if(error!=null&&!job.cancelled){final String message=error;new Handler(Looper.getMainLooper()).post(new Runnable(){public void run(){Toast.makeText(PixelInstallerService.this,message,Toast.LENGTH_LONG).show();}});}}
 }
}
